#!/usr/bin/env python3
"""Builds .tmp_agents/jobs_web1.json — five parallel React feature-module jobs sharing one foundation."""
import json, re, subprocess
from pathlib import Path
R = Path(__file__).resolve().parents[2]
def rd(p): return (R / p).read_text(encoding="utf-8")
def fb(p): return f"// ==== FILE: {p} ====\n{rd(p)}\n"

def controller_summary(path):
    s = rd(path); out = []
    for line in s.splitlines():
        if re.match(r"^const [A-Z][A-Za-z]* = z\.", line) or re.search(r"@(Get|Post|Patch|Put|Delete|Controller)\(", line):
            out.append(line.strip()[:400])
    return f"// ---- {path}\n" + "\n".join(out)
def zod_blocks(path):
    """Full multi-line zod schema definitions (const X = z.object({ ... });)."""
    s = rd(path); return "\n".join(m.group(0) for m in re.finditer(r"^const [A-Z][A-Za-z]* = z\.[\s\S]*?\n\}\);|^const [A-Z][A-Za-z]* = z\..*?;$", s, re.M))

FOUNDATION = "\n".join(fb(p) for p in ["apps/web/src/lib/api.ts", "apps/web/src/lib/auth.ts", "apps/web/src/lib/money.ts", "apps/web/src/i18n/index.ts", "apps/web/src/components/ui.tsx", "apps/web/src/app/router.tsx", "apps/web/src/features/dashboard/index.tsx"])
I18N_KEYS = rd("apps/web/src/i18n/en.ts")

SYSTEM = """You are a principal front-end engineer (React 18, TypeScript strict, Tailwind, TanStack Query, RTL/Arabic-first UX for retail POS, 15+ years). You write production UI for PharmaCore, a pharmacy management system for a Yemeni pharmacy (Arabic primary, English secondary; currencies YER_OLD/YER_NEW/SAR/USD).
OUTPUT FORMAT — STRICT: ONE JSON object only (no prose, no fences): {"files":[{"path":"<repo-relative>","content":"<full file>"}],"notes":"<≤200 words>"}. Keep total output under 24,000 tokens: dense, correct code; no re-emitting given files.
HARD RULES (tsc strict + eslint reject violations):
- TS strict with noUncheckedIndexedAccess, exactOptionalPropertyTypes (optional props: `x?: T | undefined`), verbatimModuleSyntax (`import type`), noUnusedLocals/Parameters. NO non-null assertions (`!`), NO `any` (use `unknown` + narrowing or explicit interfaces). Imports use the `@/` alias (e.g. `@/lib/api`). React function components, hooks only, default-export the page component from `src/features/<name>/index.tsx`.
- Data: TanStack Query v5 (`useQuery`, `useMutation`, `useQueryClient().invalidateQueries`). API via the given `get/post/patch/put` helpers; paths WITHOUT `/api/v1` prefix (e.g. `get("/items", { q })`). Errors are `ApiError` (message already localised by the server) → show with `<ErrorBox>` or `toast.err(e.message)`.
- Money: ALWAYS strings of minor units in API payloads (e.g. "150000" = 1,500.00). Display with `fmtMinor(amountMinor, currency, locale)`; parse user input with `parseToMinor(text, currency)` (returns null when invalid). Never use JS numbers for money. Quantities in API: `qtyInUnit` (number) for sales/purchases, `qtySsu` (string) for returns/adjustments.
- i18n: use `const { t, locale, dir } = useT()`; EVERY user-visible string via `t("key")`. You MAY add new keys: output a file `apps/web/src/i18n/<feature>.keys.ts` exporting `export const <feature>Ar: Record<string,string>` and `<feature>En` with IDENTICAL key sets (a test enforces parity). Prefix keys with your feature name (e.g. "pos.", "inv."). Arabic must be natural, pharmacy-domain Arabic (Yemen): فاتورة، لوط، صلاحية، وردية، صندوق، مورد، أمر شراء، استلام، مرتجع، ذمم.
- Layout: Tailwind only; logical properties for RTL (`ms-/me-/ps-/pe-/start/end`, never ml-/mr-/left/right); numbers in `.num` class (tabular, LTR isolate). Reuse `PageHeader, Field, Modal, Spinner, ErrorBox, Empty, Badge, toast` from `@/components/ui`. Tables: `<table>` with `<th>` / `<td>` (styled globally). Forms: controlled inputs; disable submit while mutating.
- Keyboard-first where specified (F-keys via `useEffect` keydown on window; don't hijack typing inside inputs unless the key is a function key/Escape). Focus management: autoFocus the primary input.
- Accessibility: labels on inputs (use `<Field>`), `aria-label` on icon buttons, `role="alert"` for errors.
- Tests: Vitest + @testing-library/react; `vi.mock("@/lib/api")` to stub `get/post`; wrap in `QueryClientProvider` + `MemoryRouter`. Test the most important behaviours (render with data, one mutation flow, one validation). Put tests next to the code as `*.test.tsx`.
- Performance: list pages paginate (limit/offset from API), debounce search 250ms, `useMemo` for derived totals, no heavy libs (no moment/lodash/mui).
THINK DEEPLY: match every API payload field to the zod schema given; match response shapes to the service summaries given; keep components small (≤ 250 lines each, split files)."""

API_FACTS = """## API response shapes (from the services — trust these)
- Error envelope: `{ error: { code, message, messageEn, details? }, requestId }` (ApiError exposes them).
- GET /items?q=&barcode=&limit=&offset= → `{ rows: Item[], total }`? NO — returns `Item[]` array directly (each: id, code, trade_name_ar, trade_name_en, generic_name, strength, dosage_form, rx_required, tax_bp, is_active). GET /items/:id → `{ ...item, units: Unit[] (id, name_ar, name_en, factor_to_ssu (string), level, is_ssu, can_sell, can_purchase, is_default_sale), barcodes: [{ barcode, unit_id, is_primary }], prices: [{ price_list_id, unit_id, unit_price_minor, min_price_minor }] }`. GET /barcodes/parse?code= → `{ kind: "GS1"|"EAN"|"INTERNAL", gtin?, lot?, expiry?, itemId?, unitId? }`.
- POST /items body: { tradeNameAr, tradeNameEn, genericName?, strength?, dosageForm?, manufacturer?, countryOfOrigin?, taxBp (number), rxRequired?: "NONE"|"RX"|"CONTROLLED", isReturnable?, trackExpiry?, categoryId?, units: [{ nameAr, nameEn, factorToSsu (number), level (number), isSsu?, canSell?, canPurchase?, isDefaultSale?, isDefaultPurchase?, isStockDisplay? }] } → { id }.
- GET /price-lists → [{ id, code, name_ar, name_en, currency, is_default }]. POST /prices { priceListId, itemId, unitId, unitPriceMinor, minPriceMinor? }.
- GET /inventory/locations → [{ id, code, name_ar, name_en }]. GET /inventory/items/:itemId/balances → [{ lot_id, lot_number, expiry_date (YYYY-MM-DD|null), location_id, qty_ssu (string), manual_status, unit_cost_minor }]. POST /inventory/receipts { itemId, locationId, unitId, qtyInUnit, lotNumber, expiryDate, unitCostMinor, costCurrency, businessDate?, supplierId? } → { lotId }. POST /inventory/adjustments { lotId, locationId, qtyDeltaSsu (string, signed), reason, businessDate? }. POST /inventory/transfers { lotId, fromLocationId, toLocationId, qtySsu, reason? }. POST /inventory/lots/:lotId/status { status: "NONE"|"QUARANTINED"|"BLOCKED"|"RETURNED_TO_SUPPLIER"|"DESTROYED", reason }. GET /inventory/expiry?businessDate= → [{ lot_id, item_id, trade_name_ar, lot_number, expiry_date, qty_ssu, days_left, bucket }]. GET /inventory/items/:itemId/kardex?lotId&from&to → movement rows.
- POST /sales/quote (200) and POST /sales (201): body { customerId?, currency?, businessDate?, lines: [{ itemId, unitId, qtyInUnit, unitPriceMinor?, lineDiscountBp?, lineDiscountMinor?, lotOverride?: { lotId, reason } }], invoiceDiscountBp?, invoiceDiscountMinor?, tenders: [{ method: "CASH"|"CARD"|"WALLET"|"CREDIT", currency, amountMinor, paymentRef?, cashboxId? }], changeCurrency?, overrides?: { approverUsername, approverSecret, reason, belowMin?, belowCost?, aboveOfficial?, credit? }, idempotencyKey?, notes? }. Quote → { totals: { gross, lineDiscountTotal, invoiceDiscountTotal, net, tax, total, roundingAdjustment, cogs } each `{currency, amountMinor}`, lines: [{ lineId, itemId, unitId, qtySsu, unitPrice, gross, net, tax, total, allocations: [{ lotId, lotNumber?, expiryDate?, qtySsu }], warnings }], warnings: [{ code, lineId? }] }. Post → { id, number, totals, settlement: { paid, credit, change, rounding, tenders }, warnings, journalEntryId }. Domain error codes you must handle in the UI: `sales.below_min_price`, `sales.below_cost`, `sales.above_official_price`, `sales.credit_limit_exceeded`, `discount.limit_exceeded`, `shifts.none_open`, `lot.expired`, `stock.insufficient`, `inventory.insufficient_stock` → show message and, for the first four, offer the Manager Override modal (username + PIN) that re-submits with `overrides`.
- GET /sales?from&to&customerId&limit&offset → `{ rows: [...invoice rows: id, number, business_date, customer_name, total_minor, paid_minor, credit_minor, currency, status], total }`. GET /sales/:id → `{ invoice, lines, lots, payments }`.
- GET /shifts/current → shift view `{ id, cashboxId, cashierId, status, openedAt, openingFloat: [{currency, amountMinor}], expectedCash: [...], version }` or `null`. POST /shifts/open { cashboxId, openingFloat: [{currency, amountMinor}] } → shift view. GET /shifts/:id/x-report → { type:"X", salesCount, byMethod: [...], expectedCash: [{currency, amountMinor}], ... }. POST /shifts/:id/close (200) { counts: [{currency, amountMinor}], reasons?: {CUR: text}, approver?: {username, secret} } → { currencies: [{ currency, expected, counted, variance, reason }], zReport }. GET /cash/balances → [{ id, code, name_ar, name_en, currency, balance_minor }]. GET /cashboxes → [{ id, code, name_ar, name_en, kind }].
- Returns: POST /returns/quote (200) / POST /returns (201) { invoiceId, lines: [{ lineId, qtySsu (string) }], reason: { code, text? }, businessDate?, refundToCustomerCredit?, approver? } → { id, number, refundTotal, lines, refunds: [{ method, amount }], lots: [{ lotId, qtySsu, destination }] }. GET /returns?invoiceId → { rows }. Reason codes: DAMAGED, WRONG_ITEM, EXPIRED, CUSTOMER_CHANGED_MIND, OTHER.
- Customers: GET /customers?q&limit&offset → { rows: [{ id, code, name, phone, credit_limit_minor, credit_currency, is_walk_in, is_active, version }], total }. GET /customers/:id → { ...customer, balance: {currency, amountMinor} }. POST /customers { name, phone?, address?, creditLimitMinor?, creditCurrency?, priceListId?, notes? }. PATCH /customers/:id { version, ...fields }. GET /customers/:id/statement?from&to → { opening, rows: [{ date, type, number, debit, credit, balance }], closing }. POST /customer-receipts { customerId, cashboxId, method, currency, amountMinor, businessDate?, allocations?: [{ invoiceId, amountMinor }], reference? }.
- Suppliers: GET /suppliers?q → { rows, total } (id, code, name, phone, default_currency, payment_terms_days, is_active, version); GET /suppliers/:id → { ...supplier, apBalance }; POST /suppliers { name, phone?, address?, taxNumber?, defaultCurrency?, paymentTermsDays?, earlyPaymentDays?, earlyPaymentBp? }; PATCH /suppliers/:id { version, ... }. GET /suppliers/:id/ledger → { openItems: [{ id, kind, date, dueDate, amount, remaining }], aging: [...], balance }.
- Purchase orders: POST /purchase-orders { supplierId, currency, expectedDate?, notes?, lines: [{ itemId, unitId, qtyInUnit, unitCostMinor, discount?: {bp}|{amountMinor}, bonusQtyInUnit? }], invoiceDiscount? } → { id, number, status, totals }; POST /purchase-orders/:id/approve (200); GET /purchase-orders?supplierId&status → { rows, total }; GET /purchase-orders/:id → { order, lines }. GET /purchase-orders/reorder-suggestions?itemId.
- Goods receipts: POST /goods-receipts { supplierId, purchaseOrderId?, locationId, currency, invoiceRef?, businessDate?, lines: [{ poLineId?, itemId, unitId, qtyInUnit, bonusQtyInUnit?, unitCostMinor, lotNumber, expiryDate, printedPublicPriceMinor? }], landedCosts?: [{ type: "FREIGHT"|"CUSTOMS"|"CLEARANCE"|"LOADING"|"OTHER", amountMinor, currency }] } → { id, number, lots: [...], warnings: [{ code, lineId }] }; GET /goods-receipts → { rows, total }; GET /goods-receipts/:id.
- Payables: POST /supplier-invoices { supplierId, supplierInvoiceNo, invoiceDate, currency, dueDate?, lines: [{ grnLineId?, itemId, unitId, qtyInUnit, unitCostMinor, discount?, unmatchedReason? }], invoiceDiscount?, taxBp?, approver?: {username, secret}, reason? } → { id, number, matchStatus, totals, variances }; GET /supplier-invoices → { rows, total }; GET /supplier-invoices/:id. POST /purchase-returns { supplierId, locationId, businessDate?, reason: "DAMAGED"|"EXPIRED"|"NEAR_EXPIRY"|"WRONG_ITEM"|"OVERSTOCK"|"RECALL", lines: [{ lotId, qtySsu, agreedCreditPerSsuMinor? }] }. POST /supplier-payments { supplierId, cashboxId, method, currency, amountMinor, businessDate?, allocation: { mode: "FIFO"|"PRO_RATA"|"EXPLICIT", targets?: [{ itemId, amountMinor }] }, reference? }.
- Treasury: POST /expenses { categoryId, cashboxId, currency, amountMinor, inputVatMinor?, businessDate?, description }; GET /expense-categories → [{ id, code, name_ar, name_en, account_code }]. POST /cash/transfers { fromCashboxId, toCashboxId, currency, amountMinor, toCurrency?, toAmountMinor?, businessDate?, reason }. POST /cash/fx { cashboxId, fromCurrency, fromAmountMinor, toCurrency, toAmountMinor, businessDate? }. POST /cash/owner { kind: "CAPITAL"|"OWNER_DRAWING", cashboxId, currency, amountMinor, memo }. POST /cash/movements { cashboxId, kind, currency, amountMinor (signed string), reason }. POST /accounting/opening-balances { businessDate, lines: [{ accountCode, side: "DEBIT"|"CREDIT", amountMinor, currency?, cashboxId? }] }.
- Reports (GET): /reports/trial-balance?to → { currency, rows: [{ code, name_ar, name_en, type, debit, credit, balance }], totals: { debit, credit, balanced } }; /reports/pnl?from&to → { revenue: [{code, name_ar, name_en, amount}], expenses: [...], grossProfit: { sales, returns, discounts, cogs, amount }, netProfit }; /reports/balance-sheet?to → { assets, liabilities, equity (arrays of {code,name_ar,name_en,amount}), totals, balanced }; /reports/sales?from&to&groupBy=day|month|cashier|item|category → { rows: [{ key, labelAr, labelEn, count, gross, discount, net, tax, total, cogs, grossMargin, returnRefund }], totals }; /reports/sales-by-method; /reports/top-items?limit; /reports/inventory-valuation?asOf&byLocation → { rows: [{ itemId, trade_name_ar, trade_name_en, qtySsu, valueMinor }], totals }; /reports/expiry?days&asOf → { rows: [{ lotId, itemId, trade_name_ar, lotNumber, expiryDate, qtySsu, valueMinor, bucket }] }; /reports/slow-moving?days; /reports/customer-aging?asOf and /reports/supplier-aging?asOf → { rows: [{ partyId, name, current, b1, b2, b3, over, total }] }; /reports/cashbook?cashboxId&from&to → { rows: [{ occurredAt, kind, currency, amountMinor, runningBalanceMinor, reason, documentType }] }; /reports/audit?from&to&limit → { rows }. All money fields are minor-unit strings; currency = tenant base unless stated.
- Users: GET /users → [{ id, username, display_name, locale, is_active, roles: [{ id, code }] }]; POST /users { username, displayName, password, locale?, pin?, roleIds: string[] }; PATCH /users/:id { displayName?, locale?, isActive?, roleIds?, password?, pin? }; PUT /users/:id/overrides { overrides: [{ permission, effect: "ALLOW"|"DENY", limitValue? }] }; GET /roles → [{ id, code, name_ar, name_en, permissions: string[], limits }]; POST /roles { code, nameAr, nameEn, permissions, limits }; GET /auth/permissions (public) → string[] catalogue. GET /auth/me → { userId, username, displayName, locale, permissions, tenantId }.
- Exchange rates: GET /exchange-rates → [{ from_currency, to_currency, buy_rate_scaled, sell_rate_scaled, effective_from }]; POST /exchange-rates { from, to, buyRateScaled, sellRateScaled, effectiveFrom? } (RATE_SCALE 1e6: 140 YER per SAR → "140000000").
Where a shape above says "rows", the service may return the array directly — write a tiny `rowsOf(x)` helper: `Array.isArray(x) ? x : x.rows ?? []`."""

def job(id_, model, user, max_tokens=26000):
    return {"id": id_, "model": model, "system": SYSTEM, "user": user, "out": f".tmp_agents/{id_}.json", "max_tokens": max_tokens}

